"H\",\n        \"x\": -1.8,\n        \"y\": -1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 1.8,\n        \"y\": 0.9,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 1.8,\n        \"y\": -0.9,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  },\n  {\n    \"number\": 3,\n    \"title\": \"Formation of iron chloride\",\n    \"description\": \"Iron donates one electrons to each hydrogen ion. Iron shrinks as it becomes oxidised. TThe Iron atoms bond with the chlorine atoms to create a new substance called iron chloride. This is a type of salt that dissolves into the liquid, often turning the solution a light green color.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": 0,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -1.8,\n        \"y\": 0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -1.8,\n        \"y\": -0.3,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 1.5,\n        \"y\": 0.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 1.5,\n        \"y\": -0.5,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [],\n    \"electronTransfers\": [\n      {\n        \"from\": \"fe1\",\n        \"to\": \"h1\"\n      },\n      {\n        \"from\": \"fe1\",\n        \"to\": \"h2\"\n      }\n    ],\n    \"atomOverrides\": {\n      \"fe1\": {\n        \"radiusScale\": 0.8,\n        \"dimmed\": true\n      }\n    }\n  },\n  {\n    \"number\": 4,\n    \"title\": \"Products Formed\",\n    \"description\": \"The hydrogen atoms that were kicked out find each other and pair up to form hydrogen gas. Since gas is lighter than liquid, it forms tiny bubbles that fizz and rise to the surface, escaping into the air.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": 1.8,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 0.5,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 3.1,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -2,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": -1.5,\n        \"y\": 0,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"cl1\",\n        \"to\": \"fe1\"\n      },\n      {\n        \"from\": \"cl2\",\n        \"to\": \"fe1\"\n      },\n      {\n        \"from\": \"h1\",\n        \"to\": \"h2\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {\n      \"fe1\": {\n        \"radiusScale\": 0.8,\n        \"dimmed\": true\n      }\n    }\n  }\n]",
